style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://i.pinimg.com/originals/ed/8f/9a/ed8f9a6c0d3e4e3a9f3c2e6a3f2e5e2e.jpg") no-repeat center center fixed;
    background-size: cover;
    font-family: 'Comic Neue', cursive;
    color: #ffffff;
  }

  .navbar, .footer, .game-card, .container-header, .section-content {
    background-color: rgba(0, 0, 0, 0.6) !important;
    border-radius: 10px;
    padding: 10px;
  }

  a, h1, h2, h3, h4, h5, h6, p, .text-label, .game-name, .game-description {
    color: #ff4f8b !important;
    text-shadow: 1px 1px 2px black;
  }

  .btn-primary, .btn-secondary, .btn-common {
    background-color: #ff4f8b !important;
    border: none;
    color: #000000 !important;
    border-radius: 8px;
  }

  input, textarea, select {
    background-color: rgba(0, 0, 0, 0.5) !important;
    color: #ffffff !important;
    border: 2px solid #ff4f8b !important;
    border-radius: 6px;
  }

  ::selection {
    background: #ff4f8b;
    color: #000000;
  }
}
